window.kbPageData["views/entry/k-615d371b479fd158"] = {"key":"entry/k-615d371b479fd158","state":{"route":"entry/k-615d371b479fd158"},"node":{"id":"k-615d371b479fd158","mode":"k","title":"树立和践行正确政绩观","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"3.树立和践行正确政绩观\n经党中央同意，在全党开展树立和践行正确政绩观学习教育。学习教育以县处级以上领\n导班子和领导干部特别是“一把手”为重点，于 2026 年春节假期后启动、7 月底基本结束。\n持之以恒推进全面从严治党，以立党为公、为民造福、科学决策、真抓实干为总要求，\n以一体推进学查改为抓手，教…","sources":[{"id":"d7ff4c02a336114a","label":"树立和践行正确政绩观","topic":"发展与治理","category":"非时政","text":"3.树立和践行正确政绩观\n经党中央同意，在全党开展树立和践行正确政绩观学习教育。学习教育以县处级以上领\n导班子和领导干部特别是“一把手”为重点，于 2026 年春节假期后启动、7 月底基本结束。\n持之以恒推进全面从严治党，以立党为公、为民造福、科学决策、真抓实干为总要求，\n以一体推进学查改为抓手，教育引导各级党组织和党员、干部坚持实事求是、求真务实，为\n人民出政绩、以实干出政绩。\n学习教育要坚持聚焦主题、简约务实，不分批次、不划阶段，认真落实学习研讨、查摆\n问题、整改整治、建章立制、开门教育等工作安排。\n——《关于在全党开展树立和践行正确政绩观学习教育的通知》","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":51,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-615d371b479fd158":[]}};
